222	    @Override
223	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
224	        HttpHeaders headers = new HttpHeaders();
225	        Visit visit = visitMapper.toVisit(visitFieldsDto);
226	        Pet pet = new Pet();
227	        pet.setId(petId);
228	        visit.setPet(pet);
229	        this.clinicService.saveVisit(visit);
230	        VisitDto visitDto = visitMapper.toVisitDto(visit);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
