237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner != null) {
242	            Pet pet = owner.getPet(petId);
243	            if (pet != null) {
244	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    /**
251	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
252	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
253	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
254	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
255	     *
256	     * @param city     the owner's city
257	     * @param lastName the owner's last name
258	     * @return the assigned customer code
259	     */
260	    private String nextCustomerCode(String city, String lastName) {
261	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
262	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
263	        int sequence = countOwnersInCity(city) + 1;
264	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
265	    }
266	
267	    /**
268	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
269	     * owner's city already contains this many owners.
270	     */
271	    private static final int CITY_CAPACITY = 50;
272	
273	    /**
274	     * The maximum number of owners that may be created on a single day. A create is rejected with
275	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
276	     * {@code registrationDate}.
277	     */
278	    private static final int DAILY_CREATE_LIMIT = 100;
279	
280	    /**
281	     * The number of owners that must already have been created for the current day before a new
282	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
283	     * owners already carry today's {@code registrationDate}.
284	     */
285	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
286	
287	    /**
288	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
289	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
290	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
291	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
292	     * falls on a business day.
293	     *
294	     * @param date the effective registration date
295	     * @return the same date when it is a weekday, otherwise the following Monday
296	     */
297	    private static LocalDate rollToBusinessDay(LocalDate date) {
298	        return switch (date.getDayOfWeek()) {
299	            case SATURDAY -> date.plusDays(2);
300	            case SUNDAY -> date.plusDays(1);
301	            default -> date;
302	        };
303	    }
304	
305	    /**
306	     * Counts the existing owners whose {@code registrationDate} equals the given (already
307	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
308	     * business day. Called before a new owner is saved, so the returned value reflects the number of
309	     * owners created for that day prior to this create.
310	     *
311	     * @param date the adjusted business-day registration date to count against
312	     * @return the number of existing owners registered on that date
313	     */
314	    private int countOwnersRegisteredOn(LocalDate date) {
315	        return (int) this.clinicService.findAllOwners().stream()
316	            .filter(existing -> date.equals(existing.getRegistrationDate()))
317	            .count();
318	    }
319	
320	    /**
321	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
322	     *
323	     * @param city the city to count owners for
324	     * @return the number of existing owners in that city
325	     */
326	    private int countOwnersInCity(String city) {
327	        return (int) this.clinicService.findAllOwners().stream()
328	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
329	            .count();
330	    }
331	
332	    /**
333	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
334	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
335	     *
336	     * @param customerCode     the owner's assigned customer code
337	     * @param registrationDate the owner's registration date
338	     * @return the assigned membership number
339	     */
340	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
341	        String yy = String.format("%02d", registrationDate.getYear() % 100);
342	        return String.format("%s-M%s", customerCode, yy);
343	    }
344	
345	    /**
346	     * Counts the existing owners that already share the given first name and last name, comparing
347	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
348	     * the number of namesakes that existed prior to this create.
349	     *
350	     * @param firstName the new owner's first name
351	     * @param lastName  the new owner's last name
352	     * @return the number of existing owners with the same first and last name
353	     */
354	    private int countNamesakes(String firstName, String lastName) {
355	        int count = 0;
356	        for (Owner existing : this.clinicService.findAllOwners()) {
357	            if (firstName.equalsIgnoreCase(existing.getFirstName())
358	                && lastName.equalsIgnoreCase(existing.getLastName())) {
359	                count++;
360	            }
361	        }
362	        return count;
363	    }
364	
365	    /**
366	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
367	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
368	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
369	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
370	     * string is what gets stored and returned.
371	     *
372	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
373	     *
374	     * <p>Once in E.164 form the national-number length is validated against the country code: a
375	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
376	     * number exactly 10 (see {@link #COUNTRY_NATIONAL_LENGTHS}). Country codes without a configured
377	     * rule are accepted on the general 8-to-15 digit length alone.
378	     *
379	     * @param telephone the raw telephone value supplied by the client
380	     * @return the normalized E.164 telephone number
381	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
382	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
383	     *                                 after the {@code '+'}, or the wrong national-number length for
384	     *                                 its country code)
385	     */
386	    private static String normalizeTelephone(String telephone) {
387	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
388	        String digits;
389	        if (cleaned.startsWith("+")) {
390	            digits = cleaned.substring(1);
391	        } else {
392	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
393	            digits = "61" + national;
394	        }
395	        if (!digits.matches("[0-9]{8,15}")) {
396	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
397	                "telephone could not be normalized to a valid E.164 number");
398	        }
399	        validateNationalNumberLength(digits);
400	        return "+" + digits;
401	    }
402	
403	    /**
404	     * International dialling codes mapped to the exact number of national (subscriber) digits an
405	     * E.164 number for that country must carry: {@code +61} (Australia) requires 9 national digits
406	     * and {@code +1} (NANP) requires 10. Country codes absent from this map have no length rule.
407	     */
408	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
409	
410	    /**
411	     * Validates the national-number length of an E.164 number (its digits, without the leading
412	     * {@code '+'}) against its country code. The longest configured dialling code that prefixes the
413	     * number selects the rule; if none is configured the number passes (only the general 8-to-15
414	     * digit rule applies).
415	     *
416	     * @param digits the E.164 digits without the leading {@code '+'}
417	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
418	     *                                 digits does not match the country code's required length
419	     */
420	    private static void validateNationalNumberLength(String digits) {
421	        COUNTRY_NATIONAL_LENGTHS.keySet().stream()
422	            .filter(digits::startsWith)
423	            .max(Comparator.comparingInt(String::length))
424	            .ifPresent(code -> {
425	                int nationalLength = digits.length() - code.length();
426	                if (nationalLength != COUNTRY_NATIONAL_LENGTHS.get(code)) {
427	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
428	                        "telephone must have " + COUNTRY_NATIONAL_LENGTHS.get(code)
429	                            + " national digits for country code +" + code);
430	                }
431	            });
432	    }
433	
434	    /**
435	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
436	     * containing at least one dot, none of the three sections containing whitespace or an
437	     * additional {@code @}.
438	     */
439	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
440	
441	    /**
442	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
443	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
444	     * value is then stored and returned lower-cased.
445	     *
446	     * @param email the raw email value supplied by the client, possibly {@code null}
447	     * @return the lower-cased email, or {@code null} when none was supplied
448	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
449	     *                                 is not a syntactically valid address
450	     */
451	    private static String normalizeEmail(String email) {
452	        if (email == null) {
453	            return null;
454	        }
455	        if (!EMAIL_PATTERN.matcher(email).matches()) {
456	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
457	                "email must be a syntactically valid address");
458	        }
459	        return email.toLowerCase(Locale.ROOT);
460	    }
461	
462	    /**
463	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
464	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
465	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
466	     */
467	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
468	        "NSW", new int[] {2000, 2099},
469	        "VIC", new int[] {3000, 3099},
470	        "QLD", new int[] {4000, 4099});
471	
472	    /**
473	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
474	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
475	     * four-digit format is enforced by request validation; here the value is range-checked: when the
476	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
477	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
478	     * accepts any four-digit postcode.
479	     *
480	     * @param city     the owner's city
481	     * @param postcode the owner's postcode, possibly {@code null}
482	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
483	     *                                 out of range for the city's region
484	     */
485	    private static void validatePostcode(String city, String postcode) {
486	        if (postcode == null) {
487	            return;
488	        }
489	        String region = OwnerMapper.CITY_REGION.get(city);
490	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
491	        if (range == null) {
492	            return;
493	        }
494	        int value = Integer.parseInt(postcode);
495	        if (value < range[0] || value > range[1]) {
496	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
497	                "postcode " + postcode + " is not valid for region " + region);
498	        }
499	    }
500	
501	    /**
502	     * Common street-type abbreviations expanded to their full word during address normalization.
503	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
504	     */
505	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
506	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
507	
508	    /**
509	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
510	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
511	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
512	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
513	     * address comparison (household duplicate detection and the shared household id).
514	     *
515	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
516	     *
517	     * @param address the raw address supplied by the client, possibly {@code null}
518	     * @return the normalized address
519	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
520	     *                                 after normalization (required field)
521	     */
522	    private static String normalizeAddress(String address) {
